17	package org.apache.camel.processor.errorhandler;
18	
19	import java.util.concurrent.ScheduledExecutorService;
20	
21	import org.apache.camel.CamelContext;
22	import org.apache.camel.LoggingLevel;
23	import org.apache.camel.Predicate;
24	import org.apache.camel.Processor;
25	import org.apache.camel.spi.CamelLogger;
26	import org.apache.camel.spi.ErrorHandler;
27	import org.slf4j.LoggerFactory;
28	
29	/**
30	 * Implements a <a href="http://camel.apache.org/dead-letter-channel.html">Dead Letter Channel</a> after attempting to
31	 * redeliver the message using the {@link RedeliveryPolicy}
32	 */
33	public class DeadLetterChannel extends RedeliveryErrorHandler {
34	
35	    private static final CamelLogger DEFAULT_LOGGER
36	            = new CamelLogger(LoggerFactory.getLogger(DeadLetterChannel.class), LoggingLevel.ERROR);
37	
38	    /**
39	     * Creates the dead letter channel.
40	     *
41	     * @param camelContext                 the camel context
42	     * @param output                       outer processor that should use this dead letter channel
43	     * @param logger                       logger to use for logging failures and redelivery attempts
44	     * @param redeliveryProcessor          an optional processor to run before redelivery attempt
45	     * @param redeliveryPolicy             policy for redelivery
46	     * @param deadLetter                   the failure processor to send failed exchanges to
47	     * @param deadLetterUri                an optional uri for logging purpose
48	     * @param deadLetterHandleException    whether dead letter channel should handle (and ignore) exceptions which may
49	     *                                     be thrown during sending the message to the dead letter endpoint
50	     * @param useOriginalMessagePolicy     should the original IN message be moved to the dead letter queue or the
51	     *                                     current exchange IN message?
52	     * @param useOriginalBodyPolicy        should the original IN message body be moved to the dead letter queue or the
53	     *                                     current exchange IN message body?
54	     * @param retryWhile                   retry while
55	     * @param executorService              the {@link java.util.concurrent.ScheduledExecutorService} to be used for
56	     *                                     redelivery thread pool. Can be <tt>null</tt>.
57	     * @param onPrepareProcessor           a custom {@link org.apache.camel.Processor} to prepare the
58	     *                                     {@link org.apache.camel.Exchange} before handled by the failure processor /
59	     *                                     dead letter channel.
60	     * @param onExceptionOccurredProcessor a custom {@link org.apache.camel.Processor} to process the
61	     *                                     {@link org.apache.camel.Exchange} just after an exception was thrown.
62	     */
63	    public DeadLetterChannel(CamelContext camelContext, Processor output, CamelLogger logger, Processor redeliveryProcessor,
64	                             RedeliveryPolicy redeliveryPolicy,
65	                             Processor deadLetter, String deadLetterUri,
66	                             boolean deadLetterHandleException,
67	                             boolean useOriginalMessagePolicy, boolean useOriginalBodyPolicy, Predicate retryWhile,
68	                             ScheduledExecutorService executorService, Processor onPrepareProcessor,
69	                             Processor onExceptionOccurredProcessor) {
70	
71	        super(camelContext, output, logger != null ? logger : DEFAULT_LOGGER, redeliveryProcessor, redeliveryPolicy, deadLetter,
72	              deadLetterUri,
73	              deadLetterHandleException,
74	              useOriginalMessagePolicy, useOriginalBodyPolicy, retryWhile, executorService, onPrepareProcessor,
75	              onExceptionOccurredProcessor);
76	    }
77	
78	    @Override
79	    public ErrorHandler clone(Processor output) {
80	        DeadLetterChannel answer = new DeadLetterChannel(
81	                camelContext, output, logger, redeliveryProcessor, redeliveryPolicy, deadLetter, deadLetterUri,
82	                deadLetterHandleNewException, useOriginalMessagePolicy, useOriginalBodyPolicy, retryWhilePolicy,
83	                executorService, onPrepareProcessor, onExceptionProcessor);
84	        // shallow clone is okay as we do not mutate these
85	        if (exceptionPolicies != null) {
86	            answer.exceptionPolicies = exceptionPolicies;
87	        }
88	        return answer;
89	    }
90	
91	    @Override
92	    public String toString() {
93	        if (output == null) {
94	            // if no output then don't do any description
95	            return "";
96	        }
97	        return "DeadLetterChannel[" + output + ", " + (deadLetterUri != null ? deadLetterUri : deadLetter) + "]";
98	    }
99	
100	    @Override
101	    protected boolean isRunAllowedOnPreparingShutdown() {
102	        // allow to run as we want to move the message eto DLC, instead of rejecting the message
103	        return true;
104	    }
105	
106	    @Override
107	    public boolean isDeadLetterChannel() {
108	        return true;
109	    }
110	}
