67	/**
68	 * Base redeliverable error handler that also supports a final dead letter queue in case all redelivery attempts fail.
69	 * <p/>
70	 * This implementation should contain all the error handling logic and the sub classes should only configure it
71	 * according to what they support.
72	 */
73	public abstract class RedeliveryErrorHandler extends ErrorHandlerSupport
74	        implements ErrorHandlerRedeliveryCustomizer, AsyncProcessor, ShutdownPrepared, Navigate<Processor> {
75	
76	    private static final Logger LOG = LoggerFactory.getLogger(RedeliveryErrorHandler.class);
77	
78	    // factory
79	    protected PooledExchangeTaskFactory taskFactory;
80	
81	    // state
82	    protected final AtomicInteger redeliverySleepCounter = new AtomicInteger();
83	    protected ScheduledExecutorService executorService;
84	    protected volatile boolean preparingShutdown;
85	
86	    // output
87	    protected Processor output;
88	    protected AsyncProcessor outputAsync;
89	
90	    // configuration
91	    protected final CamelContext camelContext;
92	    protected final ReactiveExecutor reactiveExecutor;
93	    protected final AsyncProcessorAwaitManager awaitManager;
94	    protected final ShutdownStrategy shutdownStrategy;
95	    protected final Processor deadLetter;
96	    protected final String deadLetterUri;
97	    protected final boolean deadLetterHandleNewException;
98	    protected final Processor redeliveryProcessor;
99	    protected final RedeliveryPolicy redeliveryPolicy;
100	    protected final Predicate retryWhilePolicy;
101	    protected final CamelLogger logger;
102	    protected final boolean useOriginalMessagePolicy;
103	    protected final boolean useOriginalBodyPolicy;
104	    protected boolean redeliveryEnabled;
105	    protected boolean simpleTask;
106	    protected final ExchangeFormatter exchangeFormatter;
107	    protected final boolean customExchangeFormatter;
108	    protected final Processor onPrepareProcessor;
109	    protected final Processor onExceptionProcessor;
110	
111	    protected RedeliveryErrorHandler(CamelContext camelContext, Processor output, CamelLogger logger,
112	                                     Processor redeliveryProcessor, RedeliveryPolicy redeliveryPolicy, Processor deadLetter,
113	                                     String deadLetterUri, boolean deadLetterHandleNewException,
114	                                     boolean useOriginalMessagePolicy,
115	                                     boolean useOriginalBodyPolicy,
116	                                     Predicate retryWhile, ScheduledExecutorService executorService,
117	                                     Processor onPrepareProcessor,
118	                                     Processor onExceptionProcessor) {
119	
120	        ObjectHelper.notNull(camelContext, "CamelContext", this);
121	        ObjectHelper.notNull(redeliveryPolicy, "RedeliveryPolicy", this);
122	
123	        this.camelContext = camelContext;
124	        this.reactiveExecutor = requireNonNull(camelContext.getCamelContextExtension().getReactiveExecutor());
125	        this.awaitManager = PluginHelper.getAsyncProcessorAwaitManager(camelContext);
126	        this.shutdownStrategy = requireNonNull(camelContext.getShutdownStrategy());
127	        this.redeliveryProcessor = redeliveryProcessor;
128	        this.deadLetter = deadLetter;
129	        this.output = output;
130	        this.outputAsync = AsyncProcessorConverterHelper.convert(output);
131	        this.redeliveryPolicy = redeliveryPolicy;
132	        this.logger = logger;
133	        this.deadLetterUri = deadLetterUri;
134	        this.deadLetterHandleNewException = deadLetterHandleNewException;
135	        this.useOriginalMessagePolicy = useOriginalMessagePolicy;
136	        this.useOriginalBodyPolicy = useOriginalBodyPolicy;
137	        this.retryWhilePolicy = retryWhile;
138	        this.executorService = executorService;
139	        this.onPrepareProcessor = onPrepareProcessor;
140	        this.onExceptionProcessor = onExceptionProcessor;
141	
142	        if (ObjectHelper.isNotEmpty(redeliveryPolicy.getExchangeFormatterRef())) {
143	            ExchangeFormatter formatter = camelContext.getRegistry()
144	                    .lookupByNameAndType(redeliveryPolicy.getExchangeFormatterRef(), ExchangeFormatter.class);
145	            if (formatter != null) {
146	                this.exchangeFormatter = formatter;
147	                this.customExchangeFormatter = true;
148	            } else {
149	                throw new IllegalArgumentException(
150	                        "Cannot find the exchangeFormatter by using reference id "
151	                                                   + redeliveryPolicy.getExchangeFormatterRef());
152	            }
153	        } else {
154	            this.customExchangeFormatter = false;
155	            this.exchangeFormatter = DEFAULT_EXCHANGE_FORMATTER;
156	            try {
157	                Integer maxChars = CamelContextHelper.parseInteger(camelContext,
158	                        camelContext.getGlobalOption(Exchange.LOG_DEBUG_BODY_MAX_CHARS));
159	                if (maxChars != null) {
160	                    DEFAULT_EXCHANGE_FORMATTER.setMaxChars(maxChars);
161	                }
162	            } catch (Exception e) {
163	                throw RuntimeCamelException.wrapRuntimeCamelException(e);
164	            }
165	        }
166	
167	        ExceptionPolicyStrategy customExceptionPolicy
168	                = CamelContextHelper.findSingleByType(camelContext, ExceptionPolicyStrategy.class);
169	        if (customExceptionPolicy != null) {
170	            exceptionPolicy = customExceptionPolicy;
171	        }
172	    }
173	
174	    @Override
175	    public void process(Exchange exchange) {
176	        if (output == null) {
177	            // no output then just return
178	            return;
179	        }
180	        awaitManager.process(this, exchange);
181	    }
182	
183	    /**
184	     * Process the exchange using redelivery error handling.
185	     */
186	    @Override
187	    public boolean process(final Exchange exchange, final AsyncCallback callback) {
188	        try {
189	            // Create the redelivery task object for this exchange (optimize to only create task can do redelivery or not)
190	            Runnable task = taskFactory.acquire(exchange, callback);
191	
192	            // Run it
193	            if (exchange.isTransacted()) {
194	                reactiveExecutor.scheduleQueue(task);
195	            } else {
196	                reactiveExecutor.scheduleMain(task);
197	            }
198	            return false;
199	        } catch (Exception e) {
200	            exchange.setException(e);
201	            callback.done(true);
202	            return true;
203	        }
204	    }
205	
206	    @Override
207	    public CompletableFuture<Exchange> processAsync(Exchange exchange) {
208	        AsyncCallbackToCompletableFutureAdapter<Exchange> callback = new AsyncCallbackToCompletableFutureAdapter<>(exchange);
209	        process(exchange, callback);
210	        return callback.getFuture();
211	    }
212	
213	    @Override
214	    public void changeOutput(Processor output) {
215	        this.output = output;
216	        this.outputAsync = AsyncProcessorConverterHelper.convert(output);
217	    }
218	
219	    @Override
220	    public boolean supportTransacted() {
221	        return false;
222	    }
223	
224	    @Override
225	    public boolean hasNext() {
226	        return output != null;
227	    }
228	
229	    @Override
230	    public List<Processor> next() {
231	        if (!hasNext()) {
232	            return null;
233	        }
234	        List<Processor> answer = new ArrayList<>(1);
235	        answer.add(output);
236	        return answer;
237	    }
238	
239	    protected boolean isRunAllowedOnPreparingShutdown() {
240	        return false;
241	    }
242	
243	    @Override
244	    public void prepareShutdown(boolean suspendOnly, boolean forced) {
245	        if (suspendOnly) {
246	            return;
247	        }
248	        // prepare for shutdown, eg do not allow redelivery if configured
249	        LOG.trace("Prepare shutdown on error handler: {}", this);
250	        preparingShutdown = true;
251	    }
252	
253	    /**
254	     * <p>
255	     * Determines the redelivery delay time by first inspecting the Message header {@link Exchange#REDELIVERY_DELAY} and
256	     * if not present, defaulting to {@link RedeliveryPolicy#calculateRedeliveryDelay(long, int)}
257	     * </p>
258	     *
259	     * <p>
260	     * In order to prevent manipulation of the RedeliveryData state, the values of
261	     * {@link RedeliveryTask#redeliveryDelay} and {@link RedeliveryTask#redeliveryCounter} are copied in.
262	     * </p>
263	     *
264	     * @param  exchange          The current exchange in question.
265	     * @param  redeliveryPolicy  The RedeliveryPolicy to use in the calculation.
266	     * @param  redeliveryDelay   The default redelivery delay from RedeliveryData
267	     * @param  redeliveryCounter The redeliveryCounter
268	     * @return                   The time to wait before the next redelivery.
269	     */
270	    protected long determineRedeliveryDelay(
271	            Exchange exchange, RedeliveryPolicy redeliveryPolicy, long redeliveryDelay, int redeliveryCounter) {
272	        Message message = exchange.getIn();
273	        Long delay = message.getHeader(Exchange.REDELIVERY_DELAY, Long.class);
274	        if (delay == null) {
275	            delay = redeliveryPolicy.calculateRedeliveryDelay(redeliveryDelay, redeliveryCounter);
276	            LOG.debug("Redelivery delay calculated as {}", delay);
277	        } else {
278	            LOG.debug("Redelivery delay is {} from Message Header [{}]", delay, Exchange.REDELIVERY_DELAY);
279	        }
280	        return delay;
281	    }
282	
283	    /**
284	     * Performs a defensive copy of the exchange if needed
285	     *
286	     * @param  exchange the exchange
287	     * @return          the defensive copy, or <tt>null</tt> if not needed (redelivery is not enabled).
288	     */
289	    protected Exchange defensiveCopyExchangeIfNeeded(Exchange exchange) {
290	        // only do a defensive copy if redelivery is enabled
291	        if (redeliveryEnabled) {
292	            return ExchangeHelper.createCopy(exchange, true);
293	        } else {
294	            return null;
295	        }
296	    }
297	
298	    /**
299	     * Strategy to determine if the exchange is done so we can continue
300	     */
301	    protected boolean isDone(Exchange exchange) {
302	        if (exchange.getExchangeExtension().isInterrupted()) {
303	            // mark the exchange to stop continue routing when interrupted
304	            // as we do not want to continue routing (for example a task has been cancelled)
305	            if (LOG.isTraceEnabled()) {
306	                LOG.trace("Is exchangeId: {} interrupted? true", exchange.getExchangeId());
307	            }
308	            exchange.setRouteStop(true);
309	            return true;
310	        }
311	
312	        // only done if the exchange hasn't failed
313	        // and it has not been handled by the failure processor
314	        // or we are exhausted
315	        boolean answer = exchange.getException() == null
316	                || ExchangeHelper.isFailureHandled(exchange)
317	                || exchange.getExchangeExtension().isRedeliveryExhausted();
318	
319	        if (LOG.isTraceEnabled()) {
320	            LOG.trace("Is exchangeId: {} done? {}", exchange.getExchangeId(), answer);
321	        }
322	        return answer;
323	    }
324	
325	    @Override
326	    public Processor getOutput() {
327	        return output;
328	    }
329	
330	    /**
331	     * Returns the dead letter that message exchanges will be sent to if the redelivery attempts fail
332	     */
333	    public Processor getDeadLetter() {
334	        return deadLetter;
335	    }
336	
337	    public String getDeadLetterUri() {
338	        return deadLetterUri;
339	    }
340	
341	    public boolean isUseOriginalMessagePolicy() {
342	        return useOriginalMessagePolicy;
343	    }
344	
345	    public boolean isUseOriginalBodyPolicy() {
346	        return useOriginalBodyPolicy;
347	    }
348	
349	    public boolean isDeadLetterHandleNewException() {
350	        return deadLetterHandleNewException;
351	    }
352	
353	    public RedeliveryPolicy getRedeliveryPolicy() {
354	        return redeliveryPolicy;
355	    }
356	
357	    public CamelLogger getLogger() {
358	        return logger;
359	    }
360	
361	    protected Predicate getDefaultHandledPredicate() {
362	        // Default is not not handle errors
363	        return null;
364	    }
365	
366	    /**
367	     * Simple task to perform calling the processor with no redelivery support
368	     */
369	    protected class SimpleTask implements PooledExchangeTask, AsyncCallback {
370	        private Exchange exchange;
371	        private AsyncCallback callback;
372	        private boolean first;
373	
374	        public SimpleTask() {
375	        }
376	
377	        public void prepare(Exchange exchange, AsyncCallback callback) {
378	            this.exchange = exchange;
379	            this.callback = callback;
380	            this.first = true;
381	        }
382	
383	        @Override
384	        public String toString() {
385	            return "SimpleTask";
386	        }
387	
388	        public void reset() {
389	            this.exchange = null;
390	            this.callback = null;
391	            this.first = true;
392	        }
393	
394	        @Override
395	        public void done(boolean doneSync) {
396	            // the run method decides what to do when we are done
397	            run();
398	        }
399	
400	        /**
401	         * Processing logic.
402	         */
403	        @Override
404	        public void run() {
405	            // can we still run
406	            if (shutdownStrategy.isForceShutdown() || isStoppingOrStopped()) {
407	                runNotAllowed();
408	                return;
409	            }
410	
411	            if (exchange.getExchangeExtension().isInterrupted()) {
412	                runInterrupted();
413	                return;
414	            }
415	
416	            if (isFailedOrBridged(exchange)) {
417	                // previous processing cause an exception
418	                handlePreviousFailure();
419	            } else if (first) {
420	                // first time call the target processor
421	                handleFirst();
422	            } else {
423	                // we are done so continue callback
424	                AsyncCallback cb = callback;
425	                taskFactory.release(this);
426	                reactiveExecutor.schedule(cb);
427	            }
428	        }
429	
430	        private static boolean isFailedOrBridged(Exchange exchange) {
431	            // only new failure if the exchange has exception
432	            // and it has not been handled by the failure processor before
433	            // or not exhausted
434	            final boolean failure = exchange.getException() != null
435	                    && !exchange.getExchangeExtension().isRedeliveryExhausted()
436	                    && !ExchangeHelper.isFailureHandled(exchange);
437	            // error handled bridged
438	            final boolean bridge = ExchangeHelper.isErrorHandlerBridge(exchange);
439	
440	            return failure || bridge;
441	        }
442	
443	        private void handleFirst() {
444	            first = false;
445	            outputAsync.process(exchange, this);
446	        }
447	
448	        /**
449	         * Handles bridged errors from consumers with bridgeErrorHandler=true.
450	         * <p>
451	         * When a consumer is configured with bridgeErrorHandler=true, exceptions that occur in the consumer are bridged
452	         * to the Camel error handler. These bridged errors are marked with ERRORHANDLER_BRIDGE=true and
453	         * RedeliveryExhausted=true properties.
454	         * <p>
455	         * This method ensures that the onException route (failure processor) is properly invoked for bridged errors,
456	         * even when handled(false) is configured. This allows error handling logic in subroutes to execute while
457	         * keeping the exchange in a failed state.
458	         * <p>
459	         * This fix addresses CAMEL-22907 where bridged errors with handled(false) were not executing the onException
460	         * route body.
461	         *
462	         * @see BridgeExceptionHandlerToErrorHandler
463	         */
464	        private void handlePreviousFailure() {
465	            handleException();
466	            onExceptionOccurred();
467	
468	            // For bridged errors, we need to invoke the failure processor (onException route)
469	            // similar to how RedeliveryTask handles exhausted redeliveries
470	            Processor failureProcessor = null;
471	            Predicate handledPredicate = null;
472	            Predicate continuedPredicate = null;
473	            boolean useOriginalInMessage = false;
474	            boolean useOriginalInBody = false;
475	
476	            Exception e = exchange.getException();
477	            if (e != null) {
478	                ExceptionPolicy exceptionPolicy = getExceptionPolicy(exchange, e);
479	                if (exceptionPolicy != null) {
480	                    Route rc = ExchangeHelper.getRoute(exchange);
481	                    if (rc != null) {
482	                        failureProcessor = rc.getOnException(exceptionPolicy.getId());
483	                    }
484	                    handledPredicate = exceptionPolicy.getHandledPolicy();
485	                    continuedPredicate = exceptionPolicy.getContinuedPolicy();
486	                    useOriginalInMessage = exceptionPolicy.isUseOriginalInMessage();
487	                    useOriginalInBody = exceptionPolicy.isUseOriginalInBody();
488	                }
489	            }
490	
491	            // Determine the target processor (failure processor or dead letter)
492	            Processor target = failureProcessor != null ? failureProcessor : deadLetter;
493	            boolean isDeadLetterChannel = isDeadLetterChannel() && target == deadLetter;
494	
495	            // If we have a target processor, deliver to it
496	            if (target != null) {
497	                deliverToFailureProcessor(target, isDeadLetterChannel, handledPredicate, continuedPredicate,
498	                        useOriginalInMessage, useOriginalInBody);
499	            } else {
500	                // No failure processor, just prepare and continue
501	                prepareExchangeAfterFailure(exchange);
502	                AsyncCallback cb = callback;
503	                taskFactory.release(this);
504	                reactiveExecutor.schedule(cb);
505	            }
506	        }
507	
508	        /**
509	         * Delivers the exchange to the failure processor (onException route) for bridged errors.
510	         * <p>
511	         * This method processes the onException route for bridged errors from consumers. It temporarily clears the
512	         * exception to allow the route to execute, then restores it based on the handled/continued predicates.
513	         * <p>
514	         * The key behavior is:
515	         * <ul>
516	         * <li>If handled(true): exception is cleared and exchange is marked as successful</li>
517	         * <li>If handled(false): exception is restored and exchange remains failed</li>
518	         * <li>If continued(true): exception is cleared but exchange continues processing</li>
519	         * </ul>
520	         *
521	         * @param processor            the failure processor (onException route) to invoke
522	         * @param isDeadLetterChannel  true if using dead letter channel
523	         * @param handledPredicate     predicate to determine if exception should be handled
524	         * @param continuedPredicate   predicate to determine if processing should continue
525	         * @param useOriginalInMessage whether to use original IN message
526	         * @param useOriginalInBody    whether to use original IN body
527	         */
528	        private void deliverToFailureProcessor(
529	                final Processor processor, final boolean isDeadLetterChannel,
530	                final Predicate handledPredicate, final Predicate continuedPredicate,
531	                final boolean useOriginalInMessage, final boolean useOriginalInBody) {
532	
533	            // we did not success so now we let the failure processor handle it
534	            // clear exception as we let the failure processor handle it
535	            Exception caught = exchange.getException();
536	            if (caught != null) {
537	                exchange.setException(null);
538	            }
539	
540	            final boolean shouldHandle = shouldHandle(exchange, handledPredicate);
541	            final boolean shouldContinue = shouldContinue(exchange, continuedPredicate);
542	
543	            // always handle if dead letter channel
544	            boolean handleOrContinue = isDeadLetterChannel || shouldHandle || shouldContinue;
545	            if (handleOrContinue) {
546	                // its handled then remove traces of redelivery attempted
547	                exchange.getIn().removeHeader(Exchange.REDELIVERED);
548	                exchange.getIn().removeHeader(Exchange.REDELIVERY_COUNTER);
549	                exchange.getIn().removeHeader(Exchange.REDELIVERY_MAX_COUNTER);
550	                exchange.getExchangeExtension().setRedeliveryExhausted(false);
551	                exchange.getExchangeExtension().setRedeliveryCounter(-1);
552	                exchange.getExchangeExtension().setRedeliveryMaxCounter(-1);
553	
554	                // and remove traces of rollback only and uow exhausted markers
555	                exchange.setRollbackOnly(false);
556	                exchange.removeProperty(ExchangePropertyKey.UNIT_OF_WORK_EXHAUSTED);
557	            }
558	
559	            // we should allow using the failure processor if we should not continue
560	            // or in case of continue then the failure processor is NOT a dead letter channel
561	            // because you can continue and still let the failure processor do some routing
562	            // before continue in the main route.
563	            boolean allowFailureProcessor = !shouldContinue || !isDeadLetterChannel;
564	
565	            if (allowFailureProcessor && processor != null) {
566	
567	                // prepare original IN message/body if it should be moved instead of current message/body
568	                if (useOriginalInMessage || useOriginalInBody) {
569	                    Message original = ExchangeHelper.getOriginalInMessage(exchange);
570	                    if (useOriginalInMessage) {
571	                        LOG.trace("Using the original IN message instead of current");
572	                        exchange.setIn(original);
573	                    } else {
574	                        LOG.trace("Using the original IN message body instead of current");
575	                        exchange.getIn().setBody(original.getBody());
576	                    }
577	                    if (exchange.hasOut()) {
578	                        LOG.trace("Removing the out message to avoid some uncertain behavior");
579	                        exchange.setOut(null);
580	                    }
581	                }
582	
583	                // reset cached streams so they can be read again
584	                MessageHelper.resetStreamCache(exchange.getIn());
585	
586	                // store the last to endpoint as the failure endpoint
587	                exchange.setProperty(ExchangePropertyKey.FAILURE_ENDPOINT,
588	                        exchange.getProperty(ExchangePropertyKey.TO_ENDPOINT));
589	                // and store the route id, so we know in which route we failed
590	                Route rc = ExchangeHelper.getRoute(exchange);
591	                if (rc != null) {
592	                    exchange.setProperty(ExchangePropertyKey.FAILURE_ROUTE_ID, rc.getRouteId());
593	                }
594	
595	                // invoke custom on prepare
596	                if (onPrepareProcessor != null) {
597	                    try {
598	                        LOG.trace("OnPrepare processor {} is processing Exchange: {}", onPrepareProcessor, exchange);
599	                        onPrepareProcessor.process(exchange);
600	                    } catch (Exception e) {
601	                        // a new exception was thrown during prepare
602	                        exchange.setException(e);
603	                    }
604	                }
605	
606	                LOG.trace("Failure processor {} is processing Exchange: {}", processor, exchange);
607	
608	                // fire event as we had a failure processor to handle it, which there is a event for
609	                final boolean deadLetterChannel = processor == deadLetter;
610	
611	                if (camelContext.getCamelContextExtension().isEventNotificationApplicable()) {
612	                    EventHelper.notifyExchangeFailureHandling(exchange.getContext(), exchange, processor, deadLetterChannel,
613	                            deadLetterUri);
614	                }
615	
616	                // the failure processor could also be asynchronous
617	                AsyncProcessor afp = AsyncProcessorConverterHelper.convert(processor);
618	                afp.process(exchange, sync -> {
619	                    LOG.trace("Failure processor done: {} processing Exchange: {}", processor, exchange);
620	                    try {
621	                        prepareExchangeAfterFailure(exchange, isDeadLetterChannel, shouldHandle, shouldContinue);
622	                        // fire event as we had a failure processor to handle it, which there is a event for
623	                        if (camelContext.getCamelContextExtension().isEventNotificationApplicable()) {
624	                            EventHelper.notifyExchangeFailureHandled(exchange.getContext(), exchange, processor,
625	                                    deadLetterChannel, deadLetterUri);
626	                        }
627	                    } finally {
628	                        // if the fault was handled asynchronously, this should be reflected in the callback as well
629	                        reactiveExecutor.schedule(callback);
630	
631	                        // create log message
632	                        String msg = "Failed delivery for " + ExchangeHelper.logIds(exchange);
633	                        msg = msg + ". Caught: " + caught;
634	                        if (isDeadLetterChannel && deadLetterUri != null) {
635	                            msg = msg + ". Handled by DeadLetterChannel: [" + URISupport.sanitizeUri(deadLetterUri) + "]";
636	                        } else {
637	                            msg = msg + ". Processed by failure processor: " + processor;
638	                        }
639	
640	                        // log that we failed delivery
641	                        logFailedDelivery(exchange, msg, null);
642	
643	                        // we are done so we can release the task
644	                        taskFactory.release(this);
645	                    }
646	                });
647	            } else {
648	                try {
649	                    // store the last to endpoint as the failure endpoint
650	                    exchange.setProperty(ExchangePropertyKey.FAILURE_ENDPOINT,
651	                            exchange.getProperty(ExchangePropertyKey.TO_ENDPOINT));
652	                    // and store the route id, so we know in which route we failed
653	                    Route rc = ExchangeHelper.getRoute(exchange);
654	                    if (rc != null) {
655	                        exchange.setProperty(ExchangePropertyKey.FAILURE_ROUTE_ID, rc.getRouteId());
656	                    }
657	
658	                    // invoke custom on prepare
659	                    if (onPrepareProcessor != null) {
660	                        try {
661	                            LOG.trace("OnPrepare processor {} is processing Exchange: {}", onPrepareProcessor, exchange);
662	                            onPrepareProcessor.process(exchange);
663	                        } catch (Exception e) {
664	                            // a new exception was thrown during prepare
665	                            exchange.setException(e);
666	                        }
667	                    }
668	                    // no processor but we need to prepare after failure as well
669	                    prepareExchangeAfterFailure(exchange, isDeadLetterChannel, shouldHandle, shouldContinue);
670	                } finally {
671	                    // callback we are done
672	                    reactiveExecutor.schedule(callback);
673	
674	                    // create log message
675	                    String msg = "Failed delivery for " + ExchangeHelper.logIds(exchange);
676	                    msg = msg + ". Caught: " + caught;
677	                    if (processor != null) {
678	                        if (deadLetterUri != null) {
679	                            msg = msg + ". Handled by DeadLetterChannel: [" + URISupport.sanitizeUri(deadLetterUri) + "]";
680	                        } else {
681	                            msg = msg + ". Processed by failure processor: " + processor;
682	                        }
683	                    }
684	
685	                    // log that we failed delivery
686	                    logFailedDelivery(exchange, msg, null);
687	
688	                    // we are done so we can release the task
689	                    taskFactory.release(this);
690	                }
691	            }
692	        }
