694	        private boolean shouldHandle(Exchange exchange, Predicate handledPredicate) {
695	            if (handledPredicate != null) {
696	                return handledPredicate.matches(exchange);
697	            }
698	            return false;
699	        }
700	
701	        private boolean shouldContinue(Exchange exchange, Predicate continuedPredicate) {
702	            if (continuedPredicate != null) {
703	                return continuedPredicate.matches(exchange);
704	            }
705	            return false;
706	        }
