708	        protected void prepareExchangeAfterFailure(
709	                final Exchange exchange, final boolean isDeadLetterChannel,
710	                final boolean shouldHandle, final boolean shouldContinue) {
711	
712	            Exception newException = exchange.getException();
713	
714	            // we could not process the exchange so we let the failure processor handled it
715	            ExchangeHelper.setFailureHandled(exchange);
716	
717	            // honor if already set a handling
718	            boolean alreadySet = exchange.getExchangeExtension().isErrorHandlerHandledSet();
719	            if (alreadySet) {
720	                boolean handled = exchange.getExchangeExtension().isErrorHandlerHandled();
721	                LOG.trace("This exchange has already been marked for handling: {}", handled);
722	                if (!handled) {
723	                    // exception not handled, put exception back in the exchange
724	                    exchange.setException(exchange.getProperty(ExchangePropertyKey.EXCEPTION_CAUGHT, Exception.class));
725	                    // and put failure endpoint back as well
726	                    exchange.setProperty(ExchangePropertyKey.FAILURE_ENDPOINT,
727	                            exchange.getProperty(ExchangePropertyKey.TO_ENDPOINT));
728	                }
729	                return;
730	            }
731	
732	            // dead letter channel is special
733	            if (shouldContinue) {
734	                LOG.trace("This exchange is continued: {}", exchange);
735	                // okay we want to continue then prepare the exchange for that as well
736	                prepareExchangeForContinue(exchange, isDeadLetterChannel);
737	            } else if (shouldHandle) {
738	                LOG.trace("This exchange is handled so its marked as not failed: {}", exchange);
739	                exchange.getExchangeExtension().setErrorHandlerHandled(true);
740	            } else {
741	                // okay the redelivery policy are not explicit set to true, so we should allow to check for some
742	                // special situations when using dead letter channel
743	                if (isDeadLetterChannel) {
744	
745	                    // DLC is always handling the first thrown exception,
746	                    // but if its a new exception then use the configured option
747	                    boolean handled = newException == null || deadLetterHandleNewException;
748	
749	                    if (handled) {
750	                        LOG.trace("This exchange is handled so its marked as not failed: {}", exchange);
751	                        exchange.getExchangeExtension().setErrorHandlerHandled(true);
752	                        return;
753	                    }
754	                }
755	
756	                // not handled by default
757	                prepareExchangeAfterFailureNotHandled(exchange);
758	            }
759	        }
