761	        private void prepareExchangeForContinue(Exchange exchange, boolean isDeadLetterChannel) {
762	            Exception e = exchange.getProperty(ExchangePropertyKey.EXCEPTION_CAUGHT, Exception.class);
763	
764	            // we continue so clear any exceptions
765	            exchange.setException(null);
766	            exchange.removeProperty(ExchangePropertyKey.EXCEPTION_CAUGHT);
767	            // clear rollback flags
768	            exchange.setRollbackOnly(false);
769	            // and remove traces of rollback only and uow exhausted markers
770	            exchange.removeProperty(ExchangePropertyKey.UNIT_OF_WORK_EXHAUSTED);
771	            // continue but keep the caused exception stored as a property
772	            // (by default we do not log the failure as we continue routing)
773	            exchange.setProperty(ExchangePropertyKey.EXCEPTION_HANDLED, e);
774	            exchange.getExchangeExtension().setErrorHandlerHandled(true);
775	
776	            LOG.trace("This exchange is continued: {}", exchange);
777	        }
