779	        private void runInterrupted() {
780	            // mark the exchange to stop continue routing when interrupted
781	            // as we do not want to continue routing (for example a task has been cancelled)
782	            if (LOG.isTraceEnabled()) {
783	                LOG.trace("Is exchangeId: {} interrupted? true", exchange.getExchangeId());
784	            }
785	            exchange.setRouteStop(true);
786	            // we should not continue routing so call callback
787	            AsyncCallback cb = callback;
788	            taskFactory.release(this);
789	            cb.done(false);
790	        }
