792	        private void runNotAllowed() {
793	            LOG.trace("Run not allowed, will reject executing exchange: {}", exchange);
794	            if (exchange.getException() == null) {
795	                exchange.setException(new RejectedExecutionException());
796	            }
797	            AsyncCallback cb = callback;
798	            taskFactory.release(this);
799	            cb.done(false);
800	        }
