802	        protected void handleException() {
803	            Exception e = exchange.getException();
804	            // e is never null
805	
806	            Throwable previous = exchange.getProperty(ExchangePropertyKey.EXCEPTION_CAUGHT, Throwable.class);
807	            if (previous != null && previous != e && e != null) {
808	                // a 2nd exception was thrown while handling a previous exception
809	                // so we need to add the previous as suppressed by the new exception
810	                // see also FatalFallbackErrorHandler
811	                Throwable[] suppressed = e.getSuppressed();
812	                boolean found = false;
813	                for (Throwable t : suppressed) {
814	                    if (t == previous) {
815	                        found = true;
816	                        break;
817	                    }
818	                }
819	                if (!found) {
820	                    // okay before adding suppression then we must be sure its not referring to same method
821	                    // which otherwise can lead to add the same exception over and over again
822	                    final boolean same = isSame(e, previous);
823	                    if (!same) {
824	                        e.addSuppressed(previous);
825	                    }
826	                }
827	            }
828	
829	            // store the original caused exception in a property, so we can restore it later
830	            if (e != null) {
831	                exchange.setProperty(ExchangePropertyKey.EXCEPTION_CAUGHT, e);
832	            }
833	
834	            // store where the exception happened
835	            Route rc = ExchangeHelper.getRoute(exchange);
836	            if (rc != null) {
837	                exchange.setProperty(ExchangePropertyKey.FAILURE_ROUTE_ID, rc.getRouteId());
838	            }
839	        }
