841	        /**
842	         * Gives an optional configured OnExceptionOccurred processor a chance to process just after an exception was
843	         * thrown while processing the Exchange. This allows to execute the processor at the same time the exception was
844	         * thrown.
845	         */
846	        protected void onExceptionOccurred() {
847	            if (onExceptionProcessor == null) {
848	                return;
849	            }
850	
851	            // run this synchronously as its just a Processor
852	            try {
853	                if (LOG.isTraceEnabled()) {
854	                    LOG.trace("OnExceptionOccurred processor {} is processing Exchange: {} due exception occurred",
855	                            onExceptionProcessor, exchange);
856	                }
857	                onExceptionProcessor.process(exchange);
858	            } catch (Exception e) {
859	                // we dont not want new exception to override existing, so log it as a WARN
860	                LOG.warn("Error during processing OnExceptionOccurred. This exception is ignored.", e);
861	            }
862	            LOG.trace("OnExceptionOccurred processor done");
863	        }
