865	        protected void prepareExchangeAfterFailure(final Exchange exchange) {
866	            // we could not process the exchange so we let the failure processor handled it
867	            ExchangeHelper.setFailureHandled(exchange);
868	
869	            // honor if already set a handling
870	            boolean alreadySet = exchange.getExchangeExtension().isErrorHandlerHandledSet();
871	            if (alreadySet) {
872	                boolean handled = exchange.getExchangeExtension().isErrorHandlerHandled();
873	                LOG.trace("This exchange has already been marked for handling: {}", handled);
874	                if (!handled) {
875	                    // exception not handled, put exception back in the exchange
876	                    exchange.setException(exchange.getProperty(ExchangePropertyKey.EXCEPTION_CAUGHT, Exception.class));
877	                    // and put failure endpoint back as well
878	                    exchange.setProperty(ExchangePropertyKey.FAILURE_ENDPOINT,
879	                            exchange.getProperty(ExchangePropertyKey.TO_ENDPOINT));
880	                }
881	                return;
882	            }
883	
884	            // not handled by default
885	            prepareExchangeAfterFailureNotHandled(exchange);
886	        }
