888	        private void prepareExchangeAfterFailureNotHandled(Exchange exchange) {
889	            LOG.trace("This exchange is not handled or continued so its marked as failed: {}", exchange);
890	            // exception not handled, put exception back in the exchange
891	            exchange.getExchangeExtension().setErrorHandlerHandled(false);
892	            exchange.setException(exchange.getProperty(ExchangePropertyKey.EXCEPTION_CAUGHT, Exception.class));
893	            // and put failure endpoint back as well
894	            exchange.setProperty(ExchangePropertyKey.FAILURE_ENDPOINT, exchange.getProperty(ExchangePropertyKey.TO_ENDPOINT));
895	            // and store the route id, so we know in which route we failed
896	            Route rc = ExchangeHelper.getRoute(exchange);
897	            if (rc != null) {
898	                exchange.setProperty(ExchangePropertyKey.FAILURE_ROUTE_ID, rc.getRouteId());
899	            }
900	
901	            if (redeliveryPolicy.isLogExhausted()) {
902	                // create log message
903	                String msg = "Failed delivery for " + ExchangeHelper.logIds(exchange);
904	                msg = msg + ". Exhausted after delivery attempt: 1 caught: " + exchange.getException();
905	
906	                // log that we failed delivery as we are exhausted
907	                logFailedDelivery(exchange, msg, null);
908	            }
909	        }
910	
911	        private void logFailedDelivery(Exchange exchange, String message, Throwable e) {
912	            if (logger == null) {
913	                return;
914	            }
915	
916	            if (e == null) {
917	                e = exchange.getProperty(ExchangePropertyKey.EXCEPTION_CAUGHT, Exception.class);
918	            }
919	
920	            if (exchange.isRollbackOnly() || exchange.isRollbackOnlyLast()) {
921	                String msg = "Rollback " + ExchangeHelper.logIds(exchange);
922	                Throwable cause = exchange.getException() != null
923	                        ? exchange.getException() : exchange.getProperty(ExchangePropertyKey.EXCEPTION_CAUGHT, Throwable.class);
924	                if (cause != null) {
925	                    msg = msg + " due: " + cause.getMessage();
926	                }
927	
928	                // should we include message history
929	                if (redeliveryPolicy.isLogExhaustedMessageHistory()) {
930	                    // only use the exchange formatter if we should log exhausted message body (and if using a custom formatter then always use it)
931	                    ExchangeFormatter formatter = customExchangeFormatter
932	                            ? exchangeFormatter
933	                            : (redeliveryPolicy.isLogExhaustedMessageBody() || camelContext.isLogExhaustedMessageBody()
934	                                    ? exchangeFormatter : null);
935	                    String routeStackTrace = MessageHelper.dumpMessageHistoryStacktrace(exchange, formatter, false);
936	                    msg = msg + "\n" + routeStackTrace;
937	                }
938	
939	                if (logger.getLevel() == LoggingLevel.ERROR) {
940	                    // log intended rollback on maximum WARN level (not ERROR)
941	                    logger.log(msg, LoggingLevel.WARN);
942	                } else {
943	                    // otherwise use the desired logging level
944	                    logger.log(msg);
945	                }
946	            } else {
947	                String msg = message;
948	                // should we include message history
949	                if (redeliveryPolicy.isLogExhaustedMessageHistory()) {
950	                    // only use the exchange formatter if we should log exhausted message body (and if using a custom formatter then always use it)
951	                    ExchangeFormatter formatter = customExchangeFormatter
952	                            ? exchangeFormatter
953	                            : (redeliveryPolicy.isLogExhaustedMessageBody() || camelContext.isLogExhaustedMessageBody()
954	                                    ? exchangeFormatter : null);
955	                    String routeStackTrace = MessageHelper.dumpMessageHistoryStacktrace(exchange, formatter,
956	                            e != null && redeliveryPolicy.isLogStackTrace());
957	                    msg = msg + "\n" + routeStackTrace;
958	                }
959	
960	                if (e != null && redeliveryPolicy.isLogStackTrace()) {
961	                    logger.log(msg, e);
962	                } else {
963	                    logger.log(msg);
964	                }
965	            }
966	        }
967	    }
