969	    /**
970	     * Task to perform calling the processor and handling redelivery if it fails (more advanced than ProcessTask)
971	     */
972	    protected class RedeliveryTask implements PooledExchangeTask {
973	        // state
974	        private Exchange original;
975	        private Exchange exchange;
976	        private AsyncCallback callback;
977	        private int redeliveryCounter;
978	        private long redeliveryDelay;
979	
980	        // default behavior which can be overloaded on a per exception basis
981	        private Predicate retryWhilePredicate;
982	        private RedeliveryPolicy currentRedeliveryPolicy;
983	        private Processor failureProcessor;
984	        private Processor onRedeliveryProcessor;
985	        private Processor onExceptionProcessor;
986	        private Predicate handledPredicate;
987	        private Predicate continuedPredicate;
988	        private boolean useOriginalInMessage;
989	        private boolean useOriginalInBody;
990	
991	        public RedeliveryTask() {
992	        }
993	
994	        @Override
995	        public String toString() {
996	            return "RedeliveryTask";
997	        }
998	
999	        @Override
1000	        public void prepare(Exchange exchange, AsyncCallback callback) {
1001	            this.retryWhilePredicate = retryWhilePolicy;
1002	            this.currentRedeliveryPolicy = redeliveryPolicy;
1003	            this.handledPredicate = getDefaultHandledPredicate();
1004	            this.useOriginalInMessage = useOriginalMessagePolicy;
1005	            this.useOriginalInBody = useOriginalBodyPolicy;
1006	            this.onRedeliveryProcessor = redeliveryProcessor;
1007	            this.onExceptionProcessor = RedeliveryErrorHandler.this.onExceptionProcessor;
1008	            // do a defensive copy of the original Exchange, which is needed for redelivery so we can ensure the
1009	            // original Exchange is being redelivered, and not a mutated Exchange
1010	            this.original = redeliveryEnabled ? defensiveCopyExchangeIfNeeded(exchange) : null;
1011	            this.exchange = exchange;
1012	            this.callback = callback;
1013	        }
1014	
1015	        @Override
1016	        public void reset() {
1017	            this.retryWhilePredicate = null;
1018	            this.currentRedeliveryPolicy = null;
1019	            this.handledPredicate = null;
1020	            this.continuedPredicate = null;
1021	            this.useOriginalInMessage = false;
1022	            this.useOriginalInBody = false;
1023	            this.onRedeliveryProcessor = null;
1024	            this.onExceptionProcessor = null;
1025	            this.original = null;
1026	            this.exchange = null;
1027	            this.callback = null;
1028	            this.redeliveryCounter = 0;
1029	            this.redeliveryDelay = 0;
1030	        }
1031	
1032	        /**
1033	         * Processing and redelivery logic.
1034	         */
1035	        @Override
1036	        public void run() {
1037	            // can we still run
1038	            if (!isRunAllowed()) {
1039	                LOG.trace("Run not allowed, will reject executing exchange: {}", exchange);
1040	                if (exchange.getException() == null) {
1041	                    exchange.setException(new RejectedExecutionException());
1042	                }
1043	                AsyncCallback cb = callback;
1044	                taskFactory.release(this);
1045	                cb.done(false);
1046	                return;
1047	            }
1048	
1049	            try {
1050	                doRun();
1051	            } catch (Exception e) {
1052	                // unexpected exception during running so set exception and trigger callback
1053	                // (do not do taskFactory.release as that happens later)
1054	                exchange.setException(e);
1055	                callback.done(false);
1056	            }
1057	        }
1058	
1059	        private void doRun() throws Exception {
1060	            // did previous processing cause an exception?
1061	            if (exchange.getException() != null) {
1062	                handleException();
1063	                onExceptionOccurred();
1064	            }
1065	
1066	            // compute if we are exhausted or cannot redeliver
1067	            boolean redeliverAllowed = redeliveryCounter == 0 || isRedeliveryAllowed();
1068	            boolean exhausted = false;
1069	            if (redeliverAllowed) {
1070	                // we can redeliver but check if we are exhausted first (optimized to only check when needed)
1071	                exhausted = exchange.getExchangeExtension().isRedeliveryExhausted() || exchange.isRollbackOnly();
1072	                if (!exhausted && redeliveryCounter > 0) {
1073	                    // its a potential redelivery so determine if we should redeliver or not
1074	                    redeliverAllowed
1075	                            = currentRedeliveryPolicy.shouldRedeliver(exchange, redeliveryCounter, retryWhilePredicate);
1076	                }
1077	            }
1078	            // if we are exhausted or redelivery is not allowed, then deliver to failure processor (eg such as DLC)
1079	            if (!redeliverAllowed || exhausted) {
1080	                Processor target = failureProcessor != null ? failureProcessor : deadLetter;
1081	                // we should always invoke the deliverToFailureProcessor as it prepares, logs and does a fair
1082	                // bit of work for exhausted exchanges (its only the target processor which may be null if handled by a savepoint)
1083	                boolean isDeadLetterChannel = isDeadLetterChannel() && target == deadLetter;
1084	                deliverToFailureProcessor(target, isDeadLetterChannel, exchange);
1085	                // we are breaking out
1086	            } else if (redeliveryCounter > 0) {
1087	                // calculate the redelivery delay
1088	                redeliveryDelay
1089	                        = determineRedeliveryDelay(exchange, currentRedeliveryPolicy, redeliveryDelay, redeliveryCounter);
1090	
1091	                if (redeliveryDelay > 0) {
1092	                    // okay there is a delay so create a scheduled task to have it executed in the future
1093	
1094	                    if (currentRedeliveryPolicy.isAsyncDelayedRedelivery() && !exchange.isTransacted()) {
1095	                        runAsynchronousRedelivery();
1096	                    } else {
1097	                        // async delayed redelivery was disabled or we are transacted so we must be synchronous
1098	                        // as the transaction manager requires to execute in the same thread context
1099	                        runSynchronousRedelivery();
1100	                    }
1101	                } else {
1102	                    // execute the task immediately
1103	                    reactiveExecutor.schedule(this::redeliver);
1104	                }
1105	            } else {
1106	                // Simple delivery
1107	                outputAsync.process(exchange, doneSync -> {
1108	                    // only continue with callback if we are done
1109	                    if (isDone(exchange)) {
1110	                        AsyncCallback cb = callback;
1111	                        taskFactory.release(this);
1112	                        reactiveExecutor.schedule(cb);
1113	                    } else {
1114	                        // error occurred so loop back around and call ourselves
1115	                        reactiveExecutor.schedule(this);
1116	                    }
1117	                });
1118	            }
1119	        }
