1135	        private void runSynchronousRedelivery() {
1136	            try {
1137	                // we are doing synchronous redelivery and use thread sleep, so we keep track using a counter how many are sleeping
1138	                redeliverySleepCounter.incrementAndGet();
1139	                boolean complete = sleep();
1140	                redeliverySleepCounter.decrementAndGet();
1141	                if (!complete) {
1142	                    // the task was rejected
1143	                    exchange.setException(new RejectedExecutionException("Redelivery not allowed while stopping"));
1144	                    // mark the exchange as redelivery exhausted so the failure processor / dead letter channel can process the exchange
1145	                    exchange.getExchangeExtension().setRedeliveryExhausted(true);
1146	                    // jump to start of loop which then detects that we are failed and exhausted
1147	                    reactiveExecutor.schedule(this);
1148	                } else {
1149	                    reactiveExecutor.schedule(this::redeliver);
1150	                }
1151	            } catch (InterruptedException e) {
1152	                redeliverySleepCounter.decrementAndGet();
1153	                // we was interrupted so break out
1154	                exchange.setException(e);
1155	                // mark the exchange to stop continue routing when interrupted
1156	                // as we do not want to continue routing (for example a task has been cancelled)
1157	                exchange.setRouteStop(true);
1158	                reactiveExecutor.schedule(callback);
1159	
1160	                Thread.currentThread().interrupt();
1161	            }
1162	        }
