1164	        protected boolean isRunAllowed() {
1165	            // if camel context is forcing a shutdown then do not allow running
1166	            if (shutdownStrategy.isForceShutdown()) {
1167	                return false;
1168	            }
1169	
1170	            // redelivery policy can control if redelivery is allowed during stopping/shutdown
1171	            // but this only applies during a redelivery (counter must > 0)
1172	            if (redeliveryCounter > 0) {
1173	                if (currentRedeliveryPolicy.allowRedeliveryWhileStopping) {
1174	                    return true;
1175	                } else if (preparingShutdown) {
1176	                    // we are preparing for shutdown, now determine if we can still run
1177	                    return isRunAllowedOnPreparingShutdown();
1178	                }
1179	            }
1180	
1181	            // we cannot run if we are stopping/stopped
1182	            return !isStoppingOrStopped();
1183	        }
