1185	        protected boolean isRedeliveryAllowed() {
1186	            // redelivery policy can control if redelivery is allowed during stopping/shutdown
1187	            // but this only applies during a redelivery (this method is only invoked when counter > 0)
1188	            boolean stopping = isStoppingOrStopped();
1189	            if (!preparingShutdown && !stopping) {
1190	                // we are not preparing to shutdown and are not stopping so we can redeliver
1191	                return true;
1192	            } else {
1193	                // we are stopping or preparing to shutdown, so see policy
1194	                return currentRedeliveryPolicy.allowRedeliveryWhileStopping;
1195	            }
1196	        }
