1198	        protected void redeliver() {
1199	            // prepare for redelivery
1200	            prepareExchangeForRedelivery();
1201	
1202	            // letting onRedeliver be executed at first
1203	            deliverToOnRedeliveryProcessor();
1204	
1205	            if (exchange.isRouteStop()) {
1206	                // the on redelivery can mark that the exchange should stop and therefore not perform a redelivery
1207	                // and if so then we are done so continue callback
1208	                AsyncCallback cb = callback;
1209	                taskFactory.release(this);
1210	                reactiveExecutor.schedule(cb);
1211	                return;
1212	            }
1213	
1214	            if (LOG.isTraceEnabled()) {
1215	                LOG.trace("Redelivering exchangeId: {} -> {} for Exchange: {}", exchange.getExchangeId(), outputAsync,
1216	                        exchange);
1217	            }
1218	
1219	            // emmit event we are doing redelivery
1220	            if (camelContext.getCamelContextExtension().isEventNotificationApplicable()) {
1221	                EventHelper.notifyExchangeRedelivery(exchange.getContext(), exchange, redeliveryCounter);
1222	            }
1223	
1224	            // process the exchange (also redelivery)
1225	            outputAsync.process(exchange, doneSync -> {
1226	                if (LOG.isTraceEnabled()) {
1227	                    LOG.trace("Redelivering exchangeId: {}", exchange.getExchangeId());
1228	                }
1229	
1230	                // only process if the exchange hasn't failed
1231	                // and it has not been handled by the error processor
1232	                if (isDone(exchange)) {
1233	                    AsyncCallback cb = callback;
1234	                    taskFactory.release(this);
1235	                    reactiveExecutor.schedule(cb);
1236	                } else {
1237	                    // error occurred so loop back around which we do by invoking the processAsyncErrorHandler
1238	                    reactiveExecutor.schedule(this);
1239	                }
1240	            });
1241	        }
