1243	        protected void prepareExchangeForContinue(Exchange exchange, boolean isDeadLetterChannel) {
1244	            Exception caught = exchange.getException();
1245	            if (caught != null) {
1246	                // we continue so clear any exceptions
1247	                exchange.setException(null);
1248	            }
1249	            // clear rollback flags
1250	            exchange.setRollbackOnly(false);
1251	            // reset cached streams so they can be read again
1252	            MessageHelper.resetStreamCache(exchange.getIn());
1253	
1254	            // its continued then remove traces of redelivery attempted and caught exception
1255	            exchange.getIn().removeHeader(Exchange.REDELIVERED);
1256	            exchange.getIn().removeHeader(Exchange.REDELIVERY_COUNTER);
1257	            exchange.getIn().removeHeader(Exchange.REDELIVERY_MAX_COUNTER);
1258	            exchange.getExchangeExtension().setFailureHandled(false);
1259	            // keep the Exchange.EXCEPTION_CAUGHT as property so end user knows the caused exception
1260	
1261	            // create log message
1262	            String msg = "Failed delivery for " + ExchangeHelper.logIds(exchange);
1263	            msg = msg + ". Exhausted after delivery attempt: " + redeliveryCounter + " caught: " + caught;
1264	            msg = msg + ". Handled and continue routing.";
1265	
1266	            // log that we failed but want to continue
1267	            logFailedDelivery(false, false, false, true, isDeadLetterChannel, exchange, msg, null);
1268	        }
