1270	        protected void prepareExchangeForRedelivery() {
1271	            if (!redeliveryEnabled) {
1272	                throw new IllegalStateException(
1273	                        "Redelivery is not enabled on " + RedeliveryErrorHandler.this
1274	                                                + ". Make sure you have configured the error handler properly.");
1275	            }
1276	            // there must be a defensive copy of the exchange
1277	            ObjectHelper.notNull(this.original, "Defensive copy of Exchange is null", RedeliveryErrorHandler.this);
1278	
1279	            // okay we will give it another go so clear the exception so we can try again
1280	            exchange.setException(null);
1281	
1282	            // clear rollback flags
1283	            exchange.setRollbackOnly(false);
1284	
1285	            // we are redelivering so copy from original back to exchange
1286	            exchange.getIn().copyFrom(this.original.getIn());
1287	            exchange.setOut(null);
1288	            // reset cached streams so they can be read again
1289	            MessageHelper.resetStreamCache(exchange.getIn());
1290	
1291	            // restore redelivery headers from internal state (not from the exchange headers,
1292	            // which user routes may have removed via removeHeaders("*"))
1293	            if (redeliveryCounter > 0) {
1294	                exchange.getIn().setHeader(Exchange.REDELIVERY_COUNTER, redeliveryCounter);
1295	                exchange.getIn().setHeader(Exchange.REDELIVERED, Boolean.TRUE);
1296	                exchange.getExchangeExtension().setRedeliveryCounter(redeliveryCounter);
1297	                if (currentRedeliveryPolicy.getMaximumRedeliveries() > 0) {
1298	                    exchange.getIn().setHeader(Exchange.REDELIVERY_MAX_COUNTER,
1299	                            currentRedeliveryPolicy.getMaximumRedeliveries());
1300	                    exchange.getExchangeExtension().setRedeliveryMaxCounter(
1301	                            currentRedeliveryPolicy.getMaximumRedeliveries());
1302	                }
1303	            }
1304	        }
