1306	        protected void handleException() {
1307	            Exception e = exchange.getException();
1308	            // e is never null
1309	
1310	            Throwable previous = exchange.getProperty(ExchangePropertyKey.EXCEPTION_CAUGHT, Throwable.class);
1311	            if (previous != null && previous != e) {
1312	                // a 2nd exception was thrown while handling a previous exception
1313	                // so we need to add the previous as suppressed by the new exception
1314	                // see also FatalFallbackErrorHandler
1315	                Throwable[] suppressed = e.getSuppressed();
1316	                boolean found = false;
1317	                for (Throwable t : suppressed) {
1318	                    if (t == previous) {
1319	                        found = true;
1320	                        break;
1321	                    }
1322	                }
1323	                if (!found) {
1324	                    // okay before adding suppression then we must be sure its not referring to same method
1325	                    // which otherwise can lead to add the same exception over and over again
1326	                    final boolean same = isSame(e, previous);
1327	                    if (!same) {
1328	                        e.addSuppressed(previous);
1329	                    }
1330	                }
1331	            }
1332	
1333	            // store the original caused exception in a property, so we can restore it later
1334	            exchange.setProperty(ExchangePropertyKey.EXCEPTION_CAUGHT, e);
1335	
1336	            // find the error handler to use (if any)
1337	            ExceptionPolicy exceptionPolicy = getExceptionPolicy(exchange, e);
1338	            if (exceptionPolicy != null) {
1339	                currentRedeliveryPolicy
1340	                        = exceptionPolicy.createRedeliveryPolicy(exchange.getContext(), currentRedeliveryPolicy);
1341	                handledPredicate = exceptionPolicy.getHandledPolicy();
1342	                continuedPredicate = exceptionPolicy.getContinuedPolicy();
1343	                retryWhilePredicate = exceptionPolicy.getRetryWhilePolicy();
1344	                useOriginalInMessage = exceptionPolicy.isUseOriginalInMessage();
1345	                useOriginalInBody = exceptionPolicy.isUseOriginalInBody();
1346	
1347	                // route specific failure handler?
1348	                Processor processor = null;
1349	                Route rc = ExchangeHelper.getRoute(exchange);
1350	                if (rc != null) {
1351	                    processor = rc.getOnException(exceptionPolicy.getId());
1352	                } else {
1353	                    // note this should really not happen, but we have this code as a fail safe
1354	                    // to be backwards compatible with the old behavior
1355	                    LOG.warn(
1356	                            "Cannot determine current route from Exchange with id: {}, will fallback and use first error handler.",
1357	                            exchange.getExchangeId());
1358	                }
1359	                if (processor != null) {
1360	                    failureProcessor = processor;
1361	                }
1362	
1363	                // route specific on redelivery?
1364	                processor = exceptionPolicy.getOnRedelivery();
1365	                if (processor != null) {
1366	                    onRedeliveryProcessor = processor;
1367	                }
1368	                // route specific on exception occurred?
1369	                processor = exceptionPolicy.getOnExceptionOccurred();
1370	                if (processor != null) {
1371	                    onExceptionProcessor = processor;
1372	                }
1373	            }
1374	
1375	            // only log if not failure handled or not an exhausted unit of work
1376	            if (!ExchangeHelper.isFailureHandled(exchange) && !ExchangeHelper.isUnitOfWorkExhausted(exchange)) {
1377	                String msg = "Failed delivery for " + ExchangeHelper.logIds(exchange)
1378	                             + ". On delivery attempt: " + redeliveryCounter + " caught: " + e;
1379	                logFailedDelivery(true, false, false, false, isDeadLetterChannel(), exchange, msg, e);
1380	            }
1381	
1382	            redeliveryCounter = incrementRedeliveryCounter(exchange);
1383	
1384	            // store where the exception happened
1385	            Route rc = ExchangeHelper.getRoute(exchange);
1386	            if (rc != null) {
1387	                exchange.setProperty(ExchangePropertyKey.FAILURE_ROUTE_ID, rc.getRouteId());
1388	            }
1389	        }
