1438	        /**
1439	         * All redelivery attempts failed so move the exchange to the dead letter queue
1440	         */
1441	        protected void deliverToFailureProcessor(
1442	                final Processor processor, final boolean isDeadLetterChannel, final Exchange exchange) {
1443	
1444	            // we did not success with the redelivery so now we let the failure processor handle it
1445	            // clear exception as we let the failure processor handle it
1446	            Exception caught = exchange.getException();
1447	            if (caught != null) {
1448	                exchange.setException(null);
1449	            }
1450	
1451	            final boolean shouldHandle = shouldHandle(exchange);
1452	            final boolean shouldContinue = shouldContinue(exchange);
1453	            // regard both handled or continued as being handled
1454	            boolean handled = false;
1455	
1456	            // always handle if dead letter channel
1457	            boolean handleOrContinue = isDeadLetterChannel || shouldHandle || shouldContinue;
1458	            if (handleOrContinue) {
1459	                // its handled then remove traces of redelivery attempted
1460	                exchange.getIn().removeHeader(Exchange.REDELIVERED);
1461	                exchange.getIn().removeHeader(Exchange.REDELIVERY_COUNTER);
1462	                exchange.getIn().removeHeader(Exchange.REDELIVERY_MAX_COUNTER);
1463	                exchange.getExchangeExtension().setRedeliveryExhausted(false);
1464	                exchange.getExchangeExtension().setRedeliveryCounter(-1);
1465	                exchange.getExchangeExtension().setRedeliveryMaxCounter(-1);
1466	
1467	                // and remove traces of rollback only and uow exhausted markers
1468	                exchange.setRollbackOnly(false);
1469	                exchange.removeProperty(ExchangePropertyKey.UNIT_OF_WORK_EXHAUSTED);
1470	
1471	                handled = true;
1472	            } else {
1473	                // must decrement the redelivery counter as we didn't process the redelivery but is
1474	                // handling by the failure handler. So we must -1 to not let the counter be out-of-sync
1475	                decrementRedeliveryCounter();
1476	            }
1477	
1478	            // we should allow using the failure processor if we should not continue
1479	            // or in case of continue then the failure processor is NOT a dead letter channel
1480	            // because you can continue and still let the failure processor do some routing
1481	            // before continue in the main route.
1482	            boolean allowFailureProcessor = !shouldContinue || !isDeadLetterChannel;
1483	            final boolean fHandled = handled;
1484	
1485	            if (allowFailureProcessor && processor != null) {
1486	
1487	                // prepare original IN message/body if it should be moved instead of current message/body
1488	                if (useOriginalInMessage || useOriginalInBody) {
1489	                    Message original = ExchangeHelper.getOriginalInMessage(exchange);
1490	                    if (useOriginalInMessage) {
1491	                        LOG.trace("Using the original IN message instead of current");
1492	                        exchange.setIn(original);
1493	                    } else {
1494	                        LOG.trace("Using the original IN message body instead of current");
1495	                        exchange.getIn().setBody(original.getBody());
1496	                    }
1497	                    if (exchange.hasOut()) {
1498	                        LOG.trace("Removing the out message to avoid some uncertain behavior");
1499	                        exchange.setOut(null);
1500	                    }
1501	                }
1502	
1503	                // reset cached streams so they can be read again
1504	                MessageHelper.resetStreamCache(exchange.getIn());
1505	
1506	                // store the last to endpoint as the failure endpoint
1507	                exchange.setProperty(ExchangePropertyKey.FAILURE_ENDPOINT,
1508	                        exchange.getProperty(ExchangePropertyKey.TO_ENDPOINT));
1509	                // and store the route id, so we know in which route we failed
1510	                Route rc = ExchangeHelper.getRoute(exchange);
1511	                if (rc != null) {
1512	                    exchange.setProperty(ExchangePropertyKey.FAILURE_ROUTE_ID, rc.getRouteId());
1513	                }
1514	
1515	                // invoke custom on prepare
1516	                if (onPrepareProcessor != null) {
1517	                    try {
1518	                        LOG.trace("OnPrepare processor {} is processing Exchange: {}", onPrepareProcessor, exchange);
1519	                        onPrepareProcessor.process(exchange);
1520	                    } catch (Exception e) {
1521	                        // a new exception was thrown during prepare
1522	                        exchange.setException(e);
1523	                    }
1524	                }
1525	
1526	                LOG.trace("Failure processor {} is processing Exchange: {}", processor, exchange);
1527	
1528	                // fire event as we had a failure processor to handle it, which there is a event for
1529	                final boolean deadLetterChannel = processor == deadLetter;
1530	
1531	                if (camelContext.getCamelContextExtension().isEventNotificationApplicable()) {
1532	                    EventHelper.notifyExchangeFailureHandling(exchange.getContext(), exchange, processor, deadLetterChannel,
1533	                            deadLetterUri);
1534	                }
1535	
1536	                // the failure processor could also be asynchronous
1537	                AsyncProcessor afp = AsyncProcessorConverterHelper.convert(processor);
1538	                afp.process(exchange, sync -> {
1539	                    LOG.trace("Failure processor done: {} processing Exchange: {}", processor, exchange);
1540	                    try {
1541	                        prepareExchangeAfterFailure(exchange, isDeadLetterChannel, shouldHandle, shouldContinue);
1542	                        // fire event as we had a failure processor to handle it, which there is a event for
1543	                        if (camelContext.getCamelContextExtension().isEventNotificationApplicable()) {
1544	                            EventHelper.notifyExchangeFailureHandled(exchange.getContext(), exchange, processor,
1545	                                    deadLetterChannel, deadLetterUri);
1546	                        }
1547	                    } finally {
1548	                        // if the fault was handled asynchronously, this should be reflected in the callback as well
1549	                        reactiveExecutor.schedule(callback);
1550	
1551	                        // create log message
1552	                        String msg = "Failed delivery for " + ExchangeHelper.logIds(exchange);
1553	                        msg = msg + ". Exhausted after delivery attempt: " + redeliveryCounter + " caught: " + caught;
1554	                        if (isDeadLetterChannel && deadLetterUri != null) {
1555	                            msg = msg + ". Handled by DeadLetterChannel: [" + URISupport.sanitizeUri(deadLetterUri) + "]";
1556	                        } else {
1557	                            msg = msg + ". Processed by failure processor: " + processor;
1558	                        }
1559	
1560	                        // log that we failed delivery as we are exhausted
1561	                        logFailedDelivery(false, false, fHandled, false, isDeadLetterChannel, exchange, msg, null);
1562	
1563	                        // we are done so we can release the task
1564	                        taskFactory.release(this);
1565	                    }
1566	                });
1567	            } else {
1568	                try {
1569	                    // store the last to endpoint as the failure endpoint
1570	                    exchange.setProperty(ExchangePropertyKey.FAILURE_ENDPOINT,
1571	                            exchange.getProperty(ExchangePropertyKey.TO_ENDPOINT));
1572	                    // and store the route id, so we know in which route we failed
1573	                    Route rc = ExchangeHelper.getRoute(exchange);
1574	                    if (rc != null) {
1575	                        exchange.setProperty(ExchangePropertyKey.FAILURE_ROUTE_ID, rc.getRouteId());
1576	                    }
1577	
1578	                    // invoke custom on prepare
1579	                    if (onPrepareProcessor != null) {
1580	                        try {
1581	                            LOG.trace("OnPrepare processor {} is processing Exchange: {}", onPrepareProcessor, exchange);
1582	                            onPrepareProcessor.process(exchange);
1583	                        } catch (Exception e) {
1584	                            // a new exception was thrown during prepare
1585	                            exchange.setException(e);
1586	                        }
1587	                    }
1588	                    // no processor but we need to prepare after failure as well
1589	                    prepareExchangeAfterFailure(exchange, isDeadLetterChannel, shouldHandle, shouldContinue);
1590	                } finally {
1591	                    // callback we are done
1592	                    reactiveExecutor.schedule(callback);
1593	
1594	                    // create log message
1595	                    String msg = "Failed delivery for " + ExchangeHelper.logIds(exchange);
1596	                    msg = msg + ". Exhausted after delivery attempt: " + redeliveryCounter + " caught: " + caught;
1597	                    if (processor != null) {
1598	                        if (deadLetterUri != null) {
1599	                            msg = msg + ". Handled by DeadLetterChannel: [" + URISupport.sanitizeUri(deadLetterUri) + "]";
1600	                        } else {
1601	                            msg = msg + ". Processed by failure processor: " + processor;
1602	                        }
1603	                    }
1604	
1605	                    // log that we failed delivery as we are exhausted
1606	                    logFailedDelivery(false, false, fHandled, false, isDeadLetterChannel, exchange, msg, null);
1607	
1608	                    // we are done so we can release the task
1609	                    taskFactory.release(this);
1610	                }
1611	            }
1612	        }
