1614	        protected void prepareExchangeAfterFailure(
1615	                final Exchange exchange, final boolean isDeadLetterChannel,
1616	                final boolean shouldHandle, final boolean shouldContinue) {
1617	
1618	            Exception newException = exchange.getException();
1619	
1620	            // we could not process the exchange so we let the failure processor handled it
1621	            ExchangeHelper.setFailureHandled(exchange);
1622	
1623	            // honor if already set a handling
1624	            boolean alreadySet = exchange.getExchangeExtension().isErrorHandlerHandledSet();
1625	            if (alreadySet) {
1626	                boolean handled = exchange.getExchangeExtension().isErrorHandlerHandled();
1627	                LOG.trace("This exchange has already been marked for handling: {}", handled);
1628	                if (!handled) {
1629	                    // exception not handled, put exception back in the exchange
1630	                    exchange.setException(exchange.getProperty(ExchangePropertyKey.EXCEPTION_CAUGHT, Exception.class));
1631	                    // and put failure endpoint back as well
1632	                    exchange.setProperty(ExchangePropertyKey.FAILURE_ENDPOINT,
1633	                            exchange.getProperty(ExchangePropertyKey.TO_ENDPOINT));
1634	                }
1635	                return;
1636	            }
1637	
1638	            // dead letter channel is special
1639	            if (shouldContinue) {
1640	                LOG.trace("This exchange is continued: {}", exchange);
1641	                // okay we want to continue then prepare the exchange for that as well
1642	                prepareExchangeForContinue(exchange, isDeadLetterChannel);
1643	            } else if (shouldHandle) {
1644	                LOG.trace("This exchange is handled so its marked as not failed: {}", exchange);
1645	                exchange.getExchangeExtension().setErrorHandlerHandled(true);
1646	            } else {
1647	                // okay the redelivery policy are not explicit set to true, so we should allow to check for some
1648	                // special situations when using dead letter channel
1649	                if (isDeadLetterChannel) {
1650	
1651	                    // DLC is always handling the first thrown exception,
1652	                    // but if its a new exception then use the configured option
1653	                    boolean handled = newException == null || deadLetterHandleNewException;
1654	
1655	                    // when using DLC then log new exception whether its being handled or not, as otherwise it may appear as
1656	                    // the DLC swallow new exceptions by default (which is by design to ensure the DLC always complete,
1657	                    // to avoid causing endless poison messages that fails forever)
1658	                    if (newException != null && currentRedeliveryPolicy.isLogNewException()) {
1659	                        String uri = URISupport.sanitizeUri(deadLetterUri);
1660	                        String msg = "New exception occurred during processing by the DeadLetterChannel[" + uri + "] due "
1661	                                     + newException.getMessage();
1662	                        if (handled) {
1663	                            msg += ". The new exception is being handled as deadLetterHandleNewException=true.";
1664	                        } else {
1665	                            msg += ". The new exception is not handled as deadLetterHandleNewException=false.";
1666	                        }
1667	                        logFailedDelivery(false, true, handled, false, true, exchange, msg, newException);
1668	                    }
1669	
1670	                    if (handled) {
1671	                        LOG.trace("This exchange is handled so its marked as not failed: {}", exchange);
1672	                        exchange.getExchangeExtension().setErrorHandlerHandled(true);
1673	                        return;
1674	                    }
1675	                }
1676	
1677	                // not handled by default
1678	                prepareExchangeAfterFailureNotHandled(exchange);
1679	            }
1680	        }
