1682	        private void prepareExchangeAfterFailureNotHandled(Exchange exchange) {
1683	            LOG.trace("This exchange is not handled or continued so its marked as failed: {}", exchange);
1684	            // exception not handled, put exception back in the exchange
1685	            exchange.getExchangeExtension().setErrorHandlerHandled(false);
1686	            exchange.setException(exchange.getProperty(ExchangePropertyKey.EXCEPTION_CAUGHT, Exception.class));
1687	            // and put failure endpoint back as well
1688	            exchange.setProperty(ExchangePropertyKey.FAILURE_ENDPOINT, exchange.getProperty(ExchangePropertyKey.TO_ENDPOINT));
1689	            // and store the route id so we know in which route we failed
1690	            String routeId = ExchangeHelper.getAtRouteId(exchange);
1691	            if (routeId != null) {
1692	                exchange.setProperty(ExchangePropertyKey.FAILURE_ROUTE_ID, routeId);
1693	            }
1694	        }
