1696	        private void logFailedDelivery(
1697	                boolean shouldRedeliver, boolean newException, boolean handled, boolean continued, boolean isDeadLetterChannel,
1698	                Exchange exchange, String message, Throwable e) {
1699	            if (logger == null) {
1700	                return;
1701	            }
1702	
1703	            if (!exchange.isRollbackOnly() && !exchange.isRollbackOnlyLast()) {
1704	                if (newException && !currentRedeliveryPolicy.isLogNewException()) {
1705	                    // do not log new exception
1706	                    return;
1707	                }
1708	
1709	                // if we should not rollback, then check whether logging is enabled
1710	
1711	                if (!newException && handled && !currentRedeliveryPolicy.isLogHandled()) {
1712	                    // do not log handled
1713	                    return;
1714	                }
1715	
1716	                if (!newException && continued && !currentRedeliveryPolicy.isLogContinued()) {
1717	                    // do not log handled
1718	                    return;
1719	                }
1720	
1721	                if (!newException && shouldRedeliver && !currentRedeliveryPolicy.isLogRetryAttempted()) {
1722	                    // do not log retry attempts
1723	                    return;
1724	                }
1725	
1726	                if (!newException && shouldRedeliver) {
1727	                    if (currentRedeliveryPolicy.isLogRetryAttempted()) {
1728	                        if (currentRedeliveryPolicy.getRetryAttemptedLogInterval() > 1
1729	                                && redeliveryCounter % currentRedeliveryPolicy.getRetryAttemptedLogInterval() != 0) {
1730	                            // do not log retry attempt because it is excluded by the retryAttemptedLogInterval
1731	                            return;
1732	                        }
1733	                    } else {
1734	                        // do not log retry attempts
1735	                        return;
1736	                    }
1737	                }
1738	
1739	                if (!newException && !shouldRedeliver && !currentRedeliveryPolicy.isLogExhausted()) {
1740	                    // do not log exhausted
1741	                    return;
1742	                }
1743	            }
1744	
1745	            LoggingLevel newLogLevel;
1746	            boolean logStackTrace;
1747	            if (exchange.isRollbackOnly() || exchange.isRollbackOnlyLast()) {
1748	                newLogLevel = currentRedeliveryPolicy.getRetriesExhaustedLogLevel();
1749	                logStackTrace = currentRedeliveryPolicy.isLogStackTrace();
1750	            } else if (shouldRedeliver) {
1751	                newLogLevel = currentRedeliveryPolicy.getRetryAttemptedLogLevel();
1752	                logStackTrace = currentRedeliveryPolicy.isLogRetryStackTrace();
1753	            } else {
1754	                newLogLevel = currentRedeliveryPolicy.getRetriesExhaustedLogLevel();
1755	                logStackTrace = currentRedeliveryPolicy.isLogStackTrace();
1756	            }
1757	            if (e == null) {
1758	                e = exchange.getProperty(ExchangePropertyKey.EXCEPTION_CAUGHT, Exception.class);
1759	            }
1760	
1761	            if (newException) {
1762	                // log at most WARN level
1763	                if (newLogLevel == LoggingLevel.ERROR) {
1764	                    newLogLevel = LoggingLevel.WARN;
1765	                }
1766	                String msg = message;
1767	                if (msg == null) {
1768	                    msg = "New exception " + ExchangeHelper.logIds(exchange);
1769	                    // special for logging the new exception
1770	                    if (e != null) {
1771	                        msg = msg + " due: " + e.getMessage();
1772	                    }
1773	                }
1774	
1775	                if (e != null && logStackTrace) {
1776	                    logger.log(msg, e, newLogLevel);
1777	                } else {
1778	                    logger.log(msg, newLogLevel);
1779	                }
1780	            } else if (exchange.isRollbackOnly() || exchange.isRollbackOnlyLast()) {
1781	                String msg = "Rollback " + ExchangeHelper.logIds(exchange);
1782	                Throwable cause = exchange.getException() != null
1783	                        ? exchange.getException() : exchange.getProperty(ExchangePropertyKey.EXCEPTION_CAUGHT, Throwable.class);
1784	                if (cause != null) {
1785	                    msg = msg + " due: " + cause.getMessage();
1786	                }
1787	
1788	                // should we include message history
1789	                if (!shouldRedeliver && currentRedeliveryPolicy.isLogExhaustedMessageHistory()) {
1790	                    // only use the exchange formatter if we should log exhausted message body (and if using a custom formatter then always use it)
1791	                    ExchangeFormatter formatter = customExchangeFormatter
1792	                            ? exchangeFormatter
1793	                            : (currentRedeliveryPolicy.isLogExhaustedMessageBody() || camelContext.isLogExhaustedMessageBody()
1794	                                    ? exchangeFormatter : null);
1795	                    String routeStackTrace = MessageHelper.dumpMessageHistoryStacktrace(exchange, formatter, false);
1796	                    msg = msg + "\n" + routeStackTrace;
1797	                }
1798	
1799	                if (newLogLevel == LoggingLevel.ERROR) {
1800	                    // log intended rollback on maximum WARN level (not ERROR)
1801	                    logger.log(msg, LoggingLevel.WARN);
1802	                } else {
1803	                    // otherwise use the desired logging level
1804	                    logger.log(msg, newLogLevel);
1805	                }
1806	            } else {
1807	                String msg = message;
1808	                // should we include message history
1809	                if (!shouldRedeliver && currentRedeliveryPolicy.isLogExhaustedMessageHistory()) {
1810	                    // only use the exchange formatter if we should log exhausted message body (and if using a custom formatter then always use it)
1811	                    ExchangeFormatter formatter = customExchangeFormatter
1812	                            ? exchangeFormatter
1813	                            : (currentRedeliveryPolicy.isLogExhaustedMessageBody() || camelContext.isLogExhaustedMessageBody()
1814	                                    ? exchangeFormatter : null);
1815	                    String routeStackTrace
1816	                            = MessageHelper.dumpMessageHistoryStacktrace(exchange, formatter, e != null && logStackTrace);
1817	                    msg = msg + "\n" + routeStackTrace;
1818	                }
1819	
1820	                if (e != null && logStackTrace) {
1821	                    logger.log(msg, e, newLogLevel);
1822	                } else {
1823	                    logger.log(msg, newLogLevel);
1824	                }
1825	            }
1826	        }
