1856	        /**
1857	         * Increments the redelivery counter and adds the redelivered flag if the message has been redelivered
1858	         */
1859	        private int incrementRedeliveryCounter(Exchange exchange) {
1860	            Message in = exchange.getIn();
1861	            // use the internal field as the authoritative counter, not the header,
1862	            // because user routes may remove headers (e.g. removeHeaders("*"))
1863	            // however, if the header carries a higher value from a nested error handler
1864	            // (e.g. per-endpoint redelivery in routing slip), respect that accumulated count
1865	            Integer counter = in.getHeader(Exchange.REDELIVERY_COUNTER, Integer.class);
1866	            int base = counter != null ? Math.max(redeliveryCounter, counter) : redeliveryCounter;
1867	            int next = base + 1;
1868	            in.setHeader(Exchange.REDELIVERY_COUNTER, next);
1869	            in.setHeader(Exchange.REDELIVERED, Boolean.TRUE);
1870	            exchange.getExchangeExtension().setRedeliveryCounter(next);
1871	            // if maximum redeliveries is used, then provide that information as well
1872	            if (currentRedeliveryPolicy.getMaximumRedeliveries() > 0) {
1873	                in.setHeader(Exchange.REDELIVERY_MAX_COUNTER, currentRedeliveryPolicy.getMaximumRedeliveries());
1874	                exchange.getExchangeExtension().setRedeliveryMaxCounter(currentRedeliveryPolicy.getMaximumRedeliveries());
1875	            }
1876	            return next;
1877	        }
1878	
1879	        /**
1880	         * Decrements the redelivery counter when the failure handler takes over without processing the redelivery.
1881	         */
1882	        private void decrementRedeliveryCounter() {
1883	            Message in = exchange.getIn();
1884	            // use the same Math.max(header, field) pattern as incrementRedeliveryCounter:
1885	            // a nested error handler may have bumped the counter in the header beyond our field
1886	            Integer counter = in.getHeader(Exchange.REDELIVERY_COUNTER, Integer.class);
1887	            int base = counter != null ? Math.max(redeliveryCounter, counter) : redeliveryCounter;
1888	            int prev = Math.max(base - 1, 0);
1889	            in.setHeader(Exchange.REDELIVERY_COUNTER, prev);
1890	            in.setHeader(Exchange.REDELIVERED, prev > 0 ? Boolean.TRUE : Boolean.FALSE);
1891	        }
