1893	        /**
1894	         * Method for sleeping during redelivery attempts.
1895	         * <p/>
1896	         * This task is for the synchronous blocking. If using async delayed then a scheduled thread pool is used for
1897	         * sleeping and trigger redeliveries.
1898	         */
1899	        @SuppressWarnings("BusyWait")
1900	        public boolean sleep() throws InterruptedException {
1901	            // for small delays then just sleep
1902	            if (redeliveryDelay < 1000) {
1903	                currentRedeliveryPolicy.sleep(redeliveryDelay);
1904	                return true;
1905	            }
1906	
1907	            StopWatch watch = new StopWatch();
1908	
1909	            LOG.debug("Sleeping for: {} millis until attempting redelivery", redeliveryDelay);
1910	            while (watch.taken() < redeliveryDelay) {
1911	                // sleep using 1 sec interval
1912	
1913	                long delta = redeliveryDelay - watch.taken();
1914	                long max = Math.min(1000, delta);
1915	                if (max > 0) {
1916	                    LOG.trace("Sleeping for: {} millis until waking up for re-check", max);
1917	                    Thread.sleep(max);
1918	                }
1919	
1920	                // are we preparing for shutdown then only do redelivery if allowed
1921	                if (preparingShutdown && !currentRedeliveryPolicy.isAllowRedeliveryWhileStopping()) {
1922	                    LOG.debug("Rejected redelivery while stopping");
1923	                    return false;
1924	                }
1925	            }
1926	
1927	            return true;
1928	        }
1929	    }
