1931	    private static boolean isSame(Exception e, Throwable previous) {
1932	        StackTraceElement[] ste1 = e.getStackTrace();
1933	        StackTraceElement[] ste2 = previous.getStackTrace();
1934	        boolean same = false;
1935	        if (ste1 != null && ste2 != null && ste1.length > 0 && ste2.length > 0) {
1936	            same = ste1[0].getClassName().equals(ste2[0].getClassName())
1937	                    && ste1[0].getLineNumber() == ste2[0].getLineNumber();
1938	        }
1939	        return same;
1940	    }
