1942	    @Override
1943	    public boolean determineIfRedeliveryIsEnabled() throws Exception {
1944	        // determine if redeliver is enabled either on error handler
1945	        if (getRedeliveryPolicy().getMaximumRedeliveries() != 0) {
1946	            // must check for != 0 as (-1 means redeliver forever)
1947	            return true;
1948	        }
1949	        if (retryWhilePolicy != null) {
1950	            return true;
1951	        }
1952	
1953	        // or on the exception policies
1954	        if (exceptionPolicies != null && !exceptionPolicies.isEmpty()) {
1955	            // walk them to see if any of them have a maximum redeliveries > 0 or retry until set
1956	            for (ExceptionPolicy def : exceptionPolicies.values()) {
1957	                if (def.determineIfRedeliveryIsEnabled(camelContext)) {
1958	                    return true;
1959	                }
1960	            }
1961	        }
1962	
1963	        return false;
1964	    }
1965	
1966	    @Override
1967	    protected void doStart() throws Exception {
1968	        // determine if redeliver is enabled or not
1969	        redeliveryEnabled = determineIfRedeliveryIsEnabled();
1970	        if (LOG.isTraceEnabled()) {
1971	            LOG.trace("Redelivery enabled: {} on error handler: {}", redeliveryEnabled, this);
1972	        }
1973	
1974	        // we only need thread pool if redelivery is enabled
1975	        if (redeliveryEnabled) {
1976	            if (executorService == null) {
1977	                // use default shared executor service
1978	                executorService = PluginHelper.getErrorHandlerExecutorService(camelContext);
1979	            }
1980	            if (LOG.isDebugEnabled()) {
1981	                LOG.debug("Using ExecutorService: {} for redeliveries on error handler: {}", executorService, this);
1982	            }
1983	        }
1984	
1985	        // reset flag when starting
1986	        preparingShutdown = false;
1987	        redeliverySleepCounter.set(0);
1988	
1989	        // calculate if we can use simple task or not
1990	        // if we need redelivery and other things then we cannot)
1991	        // however if we dont then its less memory overhead (and a bit less cpu) of using the simple task
1992	        simpleTask = deadLetter == null && !redeliveryEnabled && (exceptionPolicies == null || exceptionPolicies.isEmpty())
1993	                && onPrepareProcessor == null;
1994	
1995	        boolean pooled = camelContext.getCamelContextExtension().getExchangeFactory().isPooled();
1996	        if (pooled) {
1997	            String id = output instanceof IdAware ? ((IdAware) output).getId() : output.toString();
1998	            taskFactory = new PooledTaskFactory(id) {
1999	                @Override
2000	                public PooledExchangeTask create(Exchange exchange, AsyncCallback callback) {
2001	                    return simpleTask ? new SimpleTask() : new RedeliveryTask();
2002	                }
2003	            };
2004	            int capacity = camelContext.getCamelContextExtension().getExchangeFactory().getCapacity();
2005	            taskFactory.setCapacity(capacity);
2006	        } else {
2007	            taskFactory = new PrototypeTaskFactory() {
2008	                @Override
2009	                public PooledExchangeTask create(Exchange exchange, AsyncCallback callback) {
2010	                    return simpleTask ? new SimpleTask() : new RedeliveryTask();
2011	                }
2012	            };
2013	        }
2014	        LOG.trace("Using TaskFactory: {}", taskFactory);
2015	
2016	        ServiceHelper.startService(taskFactory, output, outputAsync, deadLetter);
2017	    }
