34	/**
35	 * The policy used to decide how many times to redeliver and the time between the redeliveries before being sent to a
36	 * <a href="http://camel.apache.org/dead-letter-channel.html">Dead Letter Channel</a>
37	 * <p>
38	 * The default values are:
39	 * <ul>
40	 * <li>maximumRedeliveries = 0</li>
41	 * <li>redeliveryDelay = 1000L (the initial delay)</li>
42	 * <li>maximumRedeliveryDelay = 60 * 1000L</li>
43	 * <li>asyncDelayedRedelivery = false</li>
44	 * <li>backOffMultiplier = 2</li>
45	 * <li>useExponentialBackOff = false</li>
46	 * <li>collisionAvoidanceFactor = 0.15d</li>
47	 * <li>useCollisionAvoidance = false</li>
48	 * <li>retriesExhaustedLogLevel = LoggingLevel.ERROR</li>
49	 * <li>retryAttemptedLogLevel = LoggingLevel.DEBUG</li>
50	 * <li>retryAttemptedLogInterval = 1</li>
51	 * <li>logRetryAttempted = true</li>
52	 * <li>logRetryStackTrace = false</li>
53	 * <li>logStackTrace = true</li>
54	 * <li>logHandled = false</li>
55	 * <li>logExhausted = true</li>
56	 * <li>logExhaustedMessageHistory = true</li>
57	 * <li>logExhaustedMessageBody = false</li>
58	 * <li>logNewException = true</li>
59	 * <li>allowRedeliveryWhileStopping = true</li>
60	 * </ul>
61	 * <p/>
62	 * Setting the maximumRedeliveries to a negative value such as -1 will then always redeliver (unlimited). Setting the
63	 * maximumRedeliveries to 0 will disable redelivery.
64	 * <p/>
65	 * This policy can be configured either by one of the following two settings:
66	 * <ul>
67	 * <li>using conventional options, using all the options defined above</li>
68	 * <li>using delay pattern to declare intervals for delays</li>
69	 * </ul>
70	 * <p/>
71	 * <b>Note:</b> If using delay patterns then the following options is not used (delay, backOffMultiplier,
72	 * useExponentialBackOff, useCollisionAvoidance)
73	 * <p/>
74	 * <b>Using delay pattern</b>: <br/>
75	 * The delay pattern syntax is: <tt>limit:delay;limit 2:delay 2;limit 3:delay 3;...;limit N:delay N</tt>.
76	 * <p/>
77	 * How it works is best illustrate with an example with this pattern: <tt>delayPattern=5:1000;10:5000:20:20000</tt>
78	 * <br/>
79	 * The delays will be for attempt in range 0..4 = 0 millis, 5..9 = 1000 millis, 10..19 = 5000 millis, >= 20 = 20000
80	 * millis.
81	 * <p/>
82	 * If you want to set a starting delay, then use 0 as the first limit, eg: <tt>0:1000;5:5000</tt> will use 1 sec delay
83	 * until attempt number 5 where it will use 5 seconds going forward.
84	 */
85	@Configurer
86	public class RedeliveryPolicy implements Cloneable, Serializable {
87	    // default policy using out of the box settings which can be shared
88	    public static final RedeliveryPolicy DEFAULT_POLICY = new RedeliveryPolicy();
