158	    /**
159	     * Returns true if the policy decides that the message exchange should be redelivered.
160	     *
161	     * @param  exchange          the current exchange
162	     * @param  redeliveryCounter the current retry counter
163	     * @param  retryWhile        an optional predicate to determine if we should redeliver or not
164	     * @return                   true to redeliver, false to stop
165	     */
166	    public boolean shouldRedeliver(Exchange exchange, int redeliveryCounter, Predicate retryWhile) {
167	        // predicate is always used if provided
168	        if (retryWhile != null) {
169	            return retryWhile.matches(exchange);
170	        }
171	
172	        if (getMaximumRedeliveries() < 0) {
173	            // retry forever if negative value
174	            return true;
175	        }
176	        // redeliver until we hit the max
177	        return redeliveryCounter <= getMaximumRedeliveries();
178	    }
