180	    /**
181	     * Calculates the new redelivery delay based on the last one and then <b>sleeps</b> for the necessary amount of
182	     * time.
183	     * <p/>
184	     * This implementation will block while sleeping.
185	     *
186	     * @param  redeliveryDelay      previous redelivery delay
187	     * @param  redeliveryCounter    number of previous redelivery attempts
188	     * @return                      the calculate delay
189	     * @throws InterruptedException is thrown if the sleep is interrupted likely because of shutdown
190	     */
191	    public long sleep(long redeliveryDelay, int redeliveryCounter) throws InterruptedException {
192	        redeliveryDelay = calculateRedeliveryDelay(redeliveryDelay, redeliveryCounter);
193	
194	        if (redeliveryDelay > 0) {
195	            sleep(redeliveryDelay);
196	        }
197	        return redeliveryDelay;
198	    }
