204	     * @throws InterruptedException is thrown if the sleep is interrupted likely because of shutdown
205	     */
206	    public void sleep(long redeliveryDelay) throws InterruptedException {
207	        LOG.debug("Sleeping for: {} millis until attempting redelivery", redeliveryDelay);
208	        Thread.sleep(redeliveryDelay);
209	    }
210	
211	    /**
212	     * Calculates the new redelivery delay based on the last one
213	     *
214	     * @param  previousDelay     previous redelivery delay
215	     * @param  redeliveryCounter number of previous redelivery attempts
216	     * @return                   the calculate delay
217	     */
218	    public long calculateRedeliveryDelay(long previousDelay, int redeliveryCounter) {
219	        if (ObjectHelper.isNotEmpty(delayPattern)) {
220	            // calculate delay using the pattern
221	            return calculateRedeliverDelayUsingPattern(delayPattern, redeliveryCounter);
222	        }
223	
224	        // calculate the delay using the conventional parameters
225	        long redeliveryDelayResult;
226	        if (previousDelay == 0) {
227	            redeliveryDelayResult = redeliveryDelay;
228	        } else if (useExponentialBackOff && backOffMultiplier > 1) {
229	            redeliveryDelayResult = Math.round(backOffMultiplier * previousDelay);
230	        } else {
231	            redeliveryDelayResult = previousDelay;
232	        }
233	
234	        if (useCollisionAvoidance) {
235	
236	            /*
237	             * First random determines +/-, second random determines how far to
238	             * go in that direction. -cgs
239	             */
240	            Random random = getRandomNumberGenerator(); // NOSONAR
241	            double variance = (random.nextBoolean() ? collisionAvoidanceFactor : -collisionAvoidanceFactor)
242	                              * random.nextDouble();
243	            redeliveryDelayResult += (long) (redeliveryDelayResult * variance);
244	        }
245	
246	        // ensure the calculated result is not bigger than the max delay (if configured)
247	        if (maximumRedeliveryDelay > 0 && redeliveryDelayResult > maximumRedeliveryDelay) {
248	            redeliveryDelayResult = maximumRedeliveryDelay;
249	        }
250	
251	        return redeliveryDelayResult;
252	    }
253	
254	    /**
255	     * Calculates the delay using the delay pattern
256	     */
257	    protected static long calculateRedeliverDelayUsingPattern(String delayPattern, int redeliveryCounter) {
258	        String[] groups = delayPattern.split(";");
259	        // find the group where the redelivery counter matches
260	        long answer = 0;
261	        for (String group : groups) {
262	            long delay = Long.parseLong(StringHelper.after(group, ":"));
263	            int count = Integer.parseInt(StringHelper.before(group, ":"));
264	            if (count > redeliveryCounter) {
265	                break;
266	            } else {
267	                answer = delay;
268	            }
269	        }
270	
271	        return answer;
272	    }
