106	    /**
107	     * Allows an exception handler to create a new redelivery policy for this exception type
108	     *
109	     * @param  context      the camel context
110	     * @param  parentPolicy the current redelivery policy, is newer <tt>null</tt>
111	     * @return              a newly created redelivery policy, or return the original policy if no customization is
112	     *                      required for this exception handler.
113	     */
114	    public RedeliveryPolicy createRedeliveryPolicy(CamelContext context, RedeliveryPolicy parentPolicy) {
115	        if (redeliveryPolicyRef != null) {
116	            return CamelContextHelper.mandatoryLookup(context, redeliveryPolicyRef, RedeliveryPolicy.class);
117	        } else if (redeliveryPolicy != null) {
118	            return createRedeliveryPolicy(redeliveryPolicy, context, parentPolicy);
119	        } else if (hasOutputs && parentPolicy.getMaximumRedeliveries() != 0) {
